internal fun vulkanExtensionReference(name: String): VulkanExtensionReference {
    val author = name.removePrefix("VK_").substringBefore("_").takeIf { it.isNotBlank() } ?: "Unknown"
    return VULKAN_EXTENSION_REFERENCE[name] ?: VulkanExtensionReference(name, author, "", "", "", "", "", "", "", "", emptyList(), emptyList(), "", "https://registry.khronos.org/vulkan/specs/latest/man/html/${name}.html")
}
